def current_rows(events):
    latest = {}
    for event in events:
        event_id = event["id"]
        key = (event["event_time"], event["seq"])
        if event_id not in latest or key >= latest[event_id][0]:
            latest[event_id] = (key, event["op"], event["value"])

    result = []
    for event_id in sorted(latest):
        _, op, value = latest[event_id]
        if op != "D":
            result.append({"id": event_id, "value": value})

    return result
